interface.definition:
a!localVariables(
  local!email,
  local!userName,
  local!selectedRole,
  local!selectedBu,
  #"SYSTEM_SYSRULES_formLayout_v1"(
    label: "Manage User",
    contents: {
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        contents: {}
      ),
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        label: "",
        contents: {
          #"SYSTEM_SYSRULES_sideBySideLayout"(
            items:{ 
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_pickerFieldUsers"(
                  label: "Select a user to Add/Remove",
                  required: true,
                  value: local!userName,
                  saveInto: {
                    local!userName,
                    if(
                      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!userName),
                      {
                        a!save(
                        local!selectedRole,
                        null
                      ),
                      a!save(
                        local!selectedBu,
                        null
                      )
                      },
                      null
                    ),
                    if(
                      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!selectedRole),
                      {
                        a!save(
                          ri!user,
                          null
                        )
                      },
                      null
                    )
                  },
                  placeholder: "-- Type user here--",
                  maxSelections: 1
                )
              ),
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_dropdownField_v1"(
                  label: "Role",
                  required: true,
                  choiceLabels: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084493",
                  choiceValues: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084493",
                  value: local!selectedRole,
                  saveInto: {
                    local!selectedRole,
                    if(
                      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!selectedRole),
                      {
                        a!save(
                          local!selectedRole,
                          null
                        ),
                        a!save(
                          ri!user.roleId,
                          null
                        )
                      },
                      null
                    ),
                    if(
                      contains({#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084493"[3],#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084493"[4]},local!selectedRole),
                      null,
                      a!save(
                        local!selectedBu,
                        null
                      )
                    )
                  },
                  placeholder: "Select a Role",
                  disabled: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!userName)
                )
              )
            }
          )
        }
      ),
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        contents: {
          #"SYSTEM_SYSRULES_sideBySideLayout"(
            items:{ 
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_textField"(
                  label: "User Name",
                  value: local!userName,
                  readOnly: true,
                  showWhen: not(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!userName))
                )
              )
            }
          )
        }
      ),
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        contents: {
          #"SYSTEM_SYSRULES_sideBySideLayout"(
            items:{ 
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_textField"(
                  label: "Email",
                  value: local!email,
                  readOnly: true,
                  showWhen: not(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!userName))
                )
              )
            }
          )
        }
      )
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_ButtonWidget"(
          label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3067846",
          submit: true,
          value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3067846",
          saveInto: {
            a!save(
              ri!user,
              null
            ),
            a!save(
              ri!action,
              save!value
            ),
            a!save(
              ri!group,
              a!groupsByName(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3085024"(local!selectedRole))
            )
          },
          style: "PRIMARY"
        ),
        #"SYSTEM_SYSRULES_ButtonWidget"(
          label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3067852",
          submit: true,
          value:#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3067852", 
          saveInto: {
            a!save(
              ri!action,
              save!value
            )
          },
          style: "DESTRUCTIVE"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_ButtonWidget"(
          label: "Cancel",
          value: true,
          saveInto: ri!cancel,
          submit: true,
          style: "NORMAL",
          validate: false
        )
      }
    )
  )
)
